import http from 'http'
import fs from 'fs'
import path from 'path'
import { chromium } from 'playwright'

const DIST = 'D:/repository/无锡市区G/dist'
const PORT = 8199
const MIME = { '.html':'text/html', '.js':'text/javascript', '.css':'text/css', '.json':'application/json', '.svg':'image/svg+xml', '.png':'image/png', '.jpg':'image/jpeg', '.woff':'font/woff', '.woff2':'font/woff2', '.ttf':'font/ttf', '.map':'application/json' }

const server = http.createServer((req, res) => {
  let url = decodeURIComponent(req.url.split('?')[0])
  let fp = path.join(DIST, url)
  if (!fs.existsSync(fp) || fs.statSync(fp).isDirectory()) {
    fp = path.join(DIST, 'index.html')
  }
  const ext = path.extname(fp)
  res.setHeader('Content-Type', MIME[ext] || 'application/octet-stream')
  fs.createReadStream(fp).pipe(res)
})

function json(obj){ return { status:200, contentType:'application/json', body: JSON.stringify(obj) } }

const tree = [
  { id:'1', label:'无锡市', children:[
    { id:'11', label:'锡山区', children:[] },
    { id:'12', label:'惠山区', children:[] }
  ]}
]
const rows = [
  { userId:1001, userName:'admin', nickName:'管理员', deptName:'无锡市', phone:'13800000000', status:'0', createTime:'2026-01-01', lastLoginTime:'2026-11-01', loginCount:10 },
  { userId:1002, userName:'test1', nickName:'测试一', deptName:'锡山区', phone:'13900000000', status:'0', createTime:'2026-01-02', lastLoginTime:'2026-11-02', loginCount:3 }
]

async function main(){
  await new Promise(r => server.listen(PORT, r))
  const browser = await chromium.launch()
  const ctx = await browser.newContext({ viewport:{ width:1920, height:900 } })
  const page = await ctx.newPage()
  page.on('console', m => { if(['error','warning'].includes(m.type())) console.log('[console.'+m.type()+']', m.text()) })
  page.on('pageerror', e => console.log('[pageerror]', e.message))

  await page.route('**/api/v2.0/**', async route => {
    const u = route.request().url()
    if (u.includes('/system/user/getInfo')) return route.fulfill(json({ code:200, user:{ userName:'admin', nickName:'管理员', deptId:'1', deptName:'无锡市', terminalType:'G', avatar:'' }, roles:['admin'], permissions:['*:*:*'] }))
    if (u.includes('/system/profile')) return route.fulfill(json({ code:200, data:{ dept:{deptName:'无锡市'}, parentDept:null } }))
    if (u.includes('/system/dept/tree')) return route.fulfill(json({ code:200, data: tree }))
    if (u.includes('/system/user/page')) return route.fulfill(json({ code:200, rows, total: rows.length }))
    if (u.includes('/dict')) return route.fulfill(json({ code:200, data: [] }))
    // generic ok
    return route.fulfill(json({ code:200, data:[], rows:[], total:0 }))
  })

  // set token before any script
  await page.addInitScript(() => { try { sessionStorage.setItem('Admin-Token', 'diag-token') } catch(e){} })

  const errors = []
  await page.goto(`http://localhost:${PORT}/#/system/user`, { waitUntil:'networkidle' }).catch(e=>errors.push('goto:'+e.message))
  await page.waitForTimeout(2500)

  const info = await page.evaluate(() => {
    const q = s => document.querySelector(s)
    const rect = el => el ? { w: Math.round(el.getBoundingClientRect().width), h: Math.round(el.getBoundingClientRect().height), display: getComputedStyle(el).display, overflow: getComputedStyle(el).overflow } : null
    const lc = q('.list-container')
    const mb = q('.main-box')
    const mr = q('.main-box-right')
    const card = q('.main-box-right .list-card')
    const sf = q('.main-box-right .search-form-container')
    const table = q('.main-box-right .el-table')
    return {
      url: location.hash,
      hasListContainer: !!lc,
      listContainer: rect(lc),
      listContainerHeight: lc ? getComputedStyle(lc).height : null,
      mainBox: rect(mb),
      mainBoxRight: rect(mr),
      mainBoxRightChildCount: mr ? mr.children.length : null,
      mainBoxRightHTMLlen: mr ? mr.innerHTML.length : null,
      searchForm: rect(sf),
      listCard: rect(card),
      table: rect(table),
      bodyText: document.body.innerText.slice(0, 120)
    }
  })
  console.log('DIAG', JSON.stringify(info, null, 2))

  await page.screenshot({ path:'D:/repository/无锡市区G/.dsh/diag-user-page.png', fullPage:false })
  if(errors.length) console.log('ERRORS', errors)
  await browser.close()
  server.close()
}
main().catch(e => { console.error('FATAL', e); try{server.close()}catch(_){}; process.exit(1) })

